=You are a lead qualification assistant for {{ $env.BUSINESS_NAME }}, a {{ $env.BUSINESS_INDUSTRY }} business.

Analyse this incoming lead and classify it.

LEAD DETAILS:
Name: {{ $json.name }}
Phone: {{ $json.phone }}
Email: {{ $json.email }}
Source: {{ $json.source }}
Service Interested In: {{ $json.service_interested_in }}
Message: {{ $json.message }}

BUSINESS INFO:
Business: {{ $env.BUSINESS_NAME }}
Industry: {{ $env.BUSINESS_INDUSTRY }}
Location: {{ $env.BUSINESS_CITY }}

Return JSON with:
{
  "lead_score": "hot|warm|cold",
  "score_reasoning": "Brief explanation of the score (1-2 sentences)",
  "urgency": "immediate|this_week|no_rush",
  "estimated_value": "low|medium|high",
  "customer_whatsapp_message": "A warm, professional WhatsApp message to send the customer confirming we received their enquiry and giving an ETA for response. 2-3 sentences. Use their first name. Sign off with business name.",
  "owner_alert_message": "A concise WhatsApp alert for the business owner. Include: lead name, score, service interested in, quick summary of message, and a suggested first response. Max 250 chars.",
  "hot_lead_email_subject": "Email subject for hot lead immediate response (only if hot)",
  "hot_lead_email_body": "Personalised email body for hot lead immediate response (only if hot). Should be warm, mention their specific service interest, offer a specific next step like booking a call or getting a quote."
}

parameters.jsCode:
// Parse Claude's response
const claudeOutput = $input.item.json.content || $input.item.json.text || $input.item.json.output || '';
let classification;
try {
  const jsonMatch = claudeOutput.match(/\{[\s\S]*\}/);
  classification = jsonMatch ? JSON.parse(jsonMatch[0]) : { lead_score: 'warm', customer_whatsapp_message: 'Thank you for your enquiry! We will be in touch shortly.', owner_alert_message: 'New lead received.' };
} catch(e) {
  classification = { lead_score: 'warm', customer_whatsapp_message: 'Thank you for your enquiry! We will be in touch shortly.', owner_alert_message: 'New lead received.' };
}

// Merge with original lead data
const lead = $('New Lead Webhook').item.json;
return {
  json: {
    ...classification,
    name: lead.name,
    phone: lead.phone,
    email: lead.email,
    source: lead.source,
    message: lead.message,
    service_interested_in: lead.service_interested_in,
    date_received: new Date().toISOString()
  }
};
